import React from "react";
import { useState, useEffect, useRef } from "react";
import Select from "react-select";
import { toast } from "react-toastify";
import { useForm } from "react-hook-form";
import api from "../api/Webcall";
import { generateUUID, compressBase64, decompressBase64, } from "../utilities/utils";
import { GetElementList } from "../utilities/getelementlist";
import { GetTaskElements } from "../utilities/getTaskElements";
import appsettings from "../../appsettings.json";

const apiendpoints = appsettings.ApiEndpoints;

function TaskElements({ ScrId }) {

  const [elementList, setElementList] = useState([]);
  const [selectedElementList, setSelectedElementList] = useState([]);
  const { register, getValues, setValue } = useForm({});
  const [selectedOption, setSelectedOption] = useState(null);

  const FetchElementList = async (ScrId, StgId) => {
    const Response = await GetElementList(ScrId, StgId);

    let elmForSelect = [];
    Response.body.elements
      .map((d, i) => {

        if (d.ParentElmName == null &&
          (d.DataTypeId == 2 || d.DataTypeId == 3 || d.DataTypeId == 4 
            || d.DataTypeId == 5 || d.DataTypeId == 6 || d.DataTypeId == 7
            || d.DataTypeId == 10)) {
          elmForSelect.push({ value: d.ElementId, label: d.ElmName });
        }

      });

    setElementList(elmForSelect);
  };

  const FetchTskElementList = async (ScrId) => {
    const TskElmList = await GetTaskElements(ScrId);
    setSelectedElementList(TskElmList.body.tskcols);
  };

  useEffect(() => {
    FetchElementList(ScrId);
    FetchTskElementList(ScrId);
  }, []);

  const callServer = async (frmData, tag, endPoint) => {

    const frmHdr = { convid: generateUUID(), tag: tag, orgid: "", vendid: "0", };

    const reqHdr = {};
    const reqdata = { hdr: frmHdr, body: frmData };

    try {
      const response = await api.post(endPoint, compressBase64(reqdata), reqHdr);
      const resData = JSON.parse(decompressBase64(response.data));

      if (resData.hdr.rst == "SUCCESS") {
        setTimeout(() => {
          toast.success("Successfully updated");
          FetchElementList(ScrId);
        }, 300);
      }
      else {
        setTimeout(() => {
          toast.error(JSON.stringify(resData.fdr[0].rstmsg));
        }, 300);
      }

    } catch (err) {
      setTimeout(() => {
        toast.error("Unable to process request");
      }, 300);
    }

  };


  const SelectedElms = (props) => {
    if (props.elmList) {
      return (

        props.elmList.map((data, index) => {

          const { ElmId, ElmNa, Hdr, Ord } = data;

          return (
            <tr key={index}>
              <td>{ElmId}</td>
              <td>{ElmNa}</td>
              <td>{Hdr}</td>
              <td>{Ord}</td>
              <td>
                <button className="btn btn-light clr-gray" onClick={() => editElement(data)} ><i className="fa fa-edit"></i></button>
                <button className="btn btn-light clr-gray" onClick={() => deleteElement(data)} ><i class="fa fa-trash-o"></i></button>
              </td>
            </tr>

          )
        })

      )
    }

  }


  const resetFormData = () => {
    setSelectedOption(null);
    setValue('txtHeading', '');
    setValue('txtOrder', '');
  };


  const handlecmbElementChange = (option) => {
    setSelectedOption(option);
  };

  const editElement = (data) => {
    var item = elementList.find(x => x.value === data.ElmId);
    setSelectedOption(item);
    setValue('txtHeading', data.Hdr);
    setValue('txtOrder', data.Ord);
  }

  const deleteElement = (data) => {

    let frmData = {
      cmbScrId: ScrId,
      ElmId: data.ElmId
    };

    callServer(frmData, "Delete Task Elements", apiendpoints.DelTaskElement);

    FetchTskElementList(ScrId);

    resetFormData();

  }

  /* Submit form */
  const onSubmitHandler = () => {

    let frmData = {
      cmbScrId: ScrId,
      ElmId: selectedOption.value,
      Hdr: getValues('txtHeading'),
      Ord: getValues('txtOrder')
    };

    callServer(frmData, "Upd Task Elements", apiendpoints.UpdTaskElement);

    FetchTskElementList(ScrId);

    resetFormData();

  };


  try {

    return (
      <>
        <div className="row">

          <div className="col-md-6">

            <div className="row">

              <div className="pad-left-15">

                <table className="lst-grid">
                  <thead>
                    <tr>
                      <th>Id</th>
                      <th>Element</th>
                      <th>Heading</th>
                      <th>Ord</th>
                      <th>Manage</th>
                    </tr>
                  </thead>
                  <tbody>
                    <SelectedElms elmList={selectedElementList} />
                  </tbody>
                </table>
              </div>

            </div>

          </div>

          <div className="col-md-6">

            <div className="row">
              <div className="col-md-6">
                <label htmlFor="cmbElement" className="form-label">Element</label>
                <Select {...register("cmbElement")} options={elementList}
                  value={selectedOption} onChange={handlecmbElementChange}> </Select>
              </div>
            </div>


            <div className="row">
              <div className="col-md-6">
                <label htmlFor="txtHeading" className="form-label">Heading</label>
                <input {...register("txtHeading")} type="text" className="form-control" />
              </div>
            </div>


            <div className="row">
              <div className="col-md-6">
                <label htmlFor="txtOrder" className="form-label">Order</label>
                <input {...register("txtOrder")} type="number" className="form-control" />
              </div>
            </div>

            <div className="row  pad-top-15">

              <div className="col-md-3">
                <button type="button" className="btn btn-success" onClick={onSubmitHandler}>
                  Submit
                </button>
              </div>

              <div className="col-md-3">
                <button type="button" className="btn btn-warning" onClick={resetFormData} >
                  Reset
                </button>
              </div>

            </div>

          </div>

        </div>
      </>
    );


  } catch (error) {
    console.log(error.message);
  }

}

export default TaskElements;
